H=http://127.0.0.1:11435
echo "===VERSION==="; curl -s -m 3 $H/api/version; echo; curl -s -m 3 $H/api/ps; echo
echo "===GEN_NOSTREAM (default)==="; time curl -s -m 60 -H "Content-Type: application/json" $H/api/generate -d '{"model":"qwen3:1.7b","prompt":"把這句話翻譯成英文，只輸出英文：今天天氣很好，我們去公園散步。","stream":false,"keep_alive":"24h","options":{"temperature":0.2,"num_predict":80}}' | python3 -c "import sys,json; d=json.load(sys.stdin); print(json.dumps({k:d.get(k) for k in ('model','response','done','done_reason','eval_count','eval_duration','prompt_eval_count','prompt_eval_duration','total_duration','load_duration')},ensure_ascii=False))"
echo "===GEN_NOSTREAM think:false==="; time curl -s -m 60 -H "Content-Type: application/json" $H/api/generate -d '{"model":"qwen3:1.7b","prompt":"把這句話翻譯成英文，只輸出英文：今天天氣很好，我們去公園散步。","stream":false,"think":false,"keep_alive":"24h","options":{"temperature":0.2,"num_predict":80}}' | python3 -c "import sys,json; d=json.load(sys.stdin); print(json.dumps({k:d.get(k) for k in ('response','thinking','done_reason','eval_count','eval_duration','prompt_eval_duration','total_duration')},ensure_ascii=False))"
echo "===GEN_NOSTREAM /no_think suffix==="; curl -s -m 60 -H "Content-Type: application/json" $H/api/generate -d '{"model":"qwen3:1.7b","prompt":"把這句話翻譯成英文，只輸出英文：今天天氣很好，我們去公園散步。 /no_think","stream":false,"keep_alive":"24h","options":{"temperature":0.2,"num_predict":80}}' | python3 -c "import sys,json; d=json.load(sys.stdin); print(json.dumps({k:d.get(k) for k in ('response','eval_count','eval_duration','total_duration')},ensure_ascii=False))"
echo "===STREAM first 6 lines + last==="; curl -s -N -m 60 -H "Content-Type: application/json" $H/api/generate -d '{"model":"qwen3:1.7b","prompt":"用繁體中文列出三個會議紀要的要點格式範例 /no_think","stream":true,"keep_alive":"24h","options":{"temperature":0.2,"num_predict":60}}' > /tmp/hs.txt; head -6 /tmp/hs.txt; echo ...; tail -1 /tmp/hs.txt; echo "lines: $(wc -l < /tmp/hs.txt)"
echo "===CHAT_API==="; curl -s -m 60 -H "Content-Type: application/json" $H/api/chat -d '{"model":"qwen3:1.7b","messages":[{"role":"system","content":"You are a translator. Output English only."},{"role":"user","content":"今天天氣很好。"}],"stream":false,"think":false,"options":{"num_predict":40}}' | head -c 600; echo
echo "===CPU_OLLAMA_BASELINE==="; time curl -s -m 60 -H "Content-Type: application/json" http://127.0.0.1:11434/api/generate -d '{"model":"qwen2.5:3b-opt","prompt":"把這句話翻譯成英文，只輸出英文：今天天氣很好，我們去公園散步。","stream":false,"keep_alive":"24h","options":{"temperature":0.2,"num_predict":80}}' | python3 -c "import sys,json; d=json.load(sys.stdin); print(json.dumps({k:d.get(k) for k in ('response','eval_count','eval_duration','prompt_eval_duration','total_duration')},ensure_ascii=False))"
